using System.Text.Json;
using VisionPluginContracts;
namespace VisionPlugins.ImageSource;
public sealed class ImageSourceEditor:Form {
 readonly ToolEditorContext context;readonly Dictionary<string,JsonElement> values;readonly Dictionary<string,Control> fields=new();readonly Panel content;readonly Label status;bool loading=true;
 int Px(int value)=>(int)Math.Round(value*DeviceDpi/96d);
 public ImageSourceEditor(ToolEditorContext context){this.context=context;values=context.Node.Parameters.ToDictionary(x=>x.Key,x=>x.Value.Clone());AutoScaleMode=AutoScaleMode.None;ClientSize=new Size(Px(420),Px(500));FormBorderStyle=FormBorderStyle.None;StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(243,243,243);Font=new Font("Microsoft YaHei UI",14*DeviceDpi/96f,FontStyle.Regular,GraphicsUnit.Pixel);var title=new Panel{Dock=DockStyle.Top,Height=Px(34),BackColor=Color.FromArgb(35,35,35)};title.Controls.Add(new Label{Text=context.Node.Name,ForeColor=Color.White,Font=new Font(Font,FontStyle.Bold),Bounds=new Rectangle(Px(10),Px(7),Px(280),Px(23))});var close=new Button{Text="×",FlatStyle=FlatStyle.Flat,ForeColor=Color.Silver,BackColor=title.BackColor,Bounds=new Rectangle(Px(380),0,Px(40),Px(34))};close.FlatAppearance.BorderSize=0;close.Click+=(_,_)=>Close();title.Controls.Add(close);var red=new Panel{Dock=DockStyle.Top,Height=2,BackColor=Color.FromArgb(245,72,48)};content=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=BackColor};status=new Label{Dock=DockStyle.Bottom,Height=Px(26),ForeColor=Color.FromArgb(120,80,35),AutoEllipsis=true};Controls.Add(content);Controls.Add(status);Controls.Add(title);Controls.Add(red);int y=20;void Group(string name){var label=new Label{Text=name,Font=new Font(Font,FontStyle.Bold),Bounds=new Rectangle(Px(32),Px(y),Px(300),Px(28)),ForeColor=Color.FromArgb(49,53,56)};content.Controls.Add(label);y+=30;}void Row(string key,string caption,Control editor){content.Controls.Add(new Label{Text=caption,Bounds=new Rectangle(Px(32),Px(y+7),Px(91),Px(28)),ForeColor=Color.FromArgb(85,89,94)});editor.Bounds=new Rectangle(Px(123),Px(y),Px(editor is ImageSourceToggle?45:262),Px(29));fields[key]=editor;content.Controls.Add(editor);y+=36;}ComboBox Enum(string key,string[] entries){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,FlatStyle=FlatStyle.Flat,BackColor=Color.White};c.Items.AddRange(entries);c.SelectedIndex=Math.Clamp(values[key].GetInt32()-1,0,entries.Length-1);c.SelectedIndexChanged+=(_,_)=>{values[key]=JsonSerializer.SerializeToElement(c.SelectedIndex+1);Apply();RefreshMode();};return c;}void Bool(string key,string label,bool supported=true){var c=new ImageSourceToggle{Checked=values[key].GetBoolean(),BackColor=values[key].GetBoolean()?Color.FromArgb(240,110,0):Color.Silver,Enabled=supported};c.CheckedChanged+=(_,_)=>{c.BackColor=c.Checked?Color.FromArgb(240,110,0):Color.Silver;values[key]=JsonSerializer.SerializeToElement(c.Checked);Apply();RefreshMode();};Row(key,label,c);}void Number(string key,string label){var c=new NumericUpDown{Minimum=0,Maximum=int.MaxValue,Value=values[key].GetInt32()};c.ValueChanged+=(_,_)=>{values[key]=JsonSerializer.SerializeToElement((int)c.Value);Apply();RefreshMode();};Row(key,label,c);}Group("基本参数");Row("ImageSourceType","图像源",Enum("ImageSourceType",["本地图像","相机","SDK"]));Row("PixelFormat","像素格式",Enum("PixelFormat",["MONO8","RGB24"]));Bool("SolSaveImageData","方案存图",false);Bool("ShowImageName","显示图像名称");Number("InitialSN","SN初始值");Number("PathCache","图片缓存");Bool("StitchEnable","拼接使能",false);y+=12;Group("触发设置");Bool("AutoPlay","自动切换");Bool("AutoStop","最后一张停止");Bool("TriggerStringEnable","字符触发过滤",false);y+=12;Group("订阅文件夹");Bool("IsSubscribeFolderMode","文件夹模式");var folder=new TextBox{Text=values["SubscribeFolderPath"].GetString()??""};folder.Validated+=(_,_)=>{values["SubscribeFolderPath"]=JsonSerializer.SerializeToElement(folder.Text);Apply();};Row("SubscribeFolderPath","图像路径",folder);Bool("RefreshImage","刷新文件夹",false);Bool("TriggerProcessRun","触发流程",false);y+=12;Group("本地图像");var files=new ListBox{Bounds=new Rectangle(Px(32),Px(y),Px(353),Px(100)),HorizontalScrollbar=true};foreach(var p in JsonSerializer.Deserialize<string[]>(values["ImagePaths"].GetString()??"[]")??[])files.Items.Add(p);content.Controls.Add(files);y+=105;var buttons=new FlowLayoutPanel{Bounds=new Rectangle(Px(32),Px(y),Px(360),Px(35))};var add=new Button{Text="添加图像",Width=Px(85),Height=Px(30)};var remove=new Button{Text="删除",Width=Px(65),Height=Px(30)};var run=new Button{Text="单次运行",Width=Px(95),Height=Px(30)};void SaveFiles(){values["ImagePaths"]=JsonSerializer.SerializeToElement(JsonSerializer.Serialize(files.Items.Cast<string>().ToArray()));if(files.Items.Count>0)values["CurrentImagePath"]=JsonSerializer.SerializeToElement(files.Items[0]?.ToString()??"");Apply();}add.Click+=(_,_)=>{using var picker=new OpenFileDialog{Filter="BMP 图像|*.bmp",Multiselect=true};if(picker.ShowDialog(this)==DialogResult.OK){foreach(var p in picker.FileNames)if(!files.Items.Contains(p))files.Items.Add(p);SaveFiles();}};remove.Click+=(_,_)=>{if(files.SelectedIndex>=0){files.Items.RemoveAt(files.SelectedIndex);SaveFiles();}};run.Click+=async(_,_)=>{run.Enabled=false;try{var record=await context.Run(new(values));status.Text=record.Status+" · "+record.Message;}catch(Exception ex){status.Text=ex.Message;}finally{run.Enabled=true;}};buttons.Controls.AddRange([add,remove,run]);content.Controls.Add(buttons);loading=false;RefreshMode();}
 void Apply(){if(loading)return;try{context.Apply(new(values));status.Text="参数已应用";}catch(Exception ex){status.Text=ex.Message;}}
 void RefreshMode(){if(!fields.TryGetValue("ImageSourceType",out var source))return;int mode=((ComboBox)source).SelectedIndex+1;foreach(string key in new[]{"PixelFormat","AutoPlay","AutoStop","PathCache","ShowImageName"})fields[key].Enabled=mode==1;fields["SubscribeFolderPath"].Visible=values["IsSubscribeFolderMode"].GetBoolean();if(!loading)status.Text=mode==1?"本地图像模式":mode==2?"相机提供器尚未接入":"SDK 图像提供器尚未接入";}
}
